diff --git a/package/contents/ui/configGeneral.qml b/package/contents/ui/configGeneral.qml
new file mode 100644
index 0000000..797c965
--- /dev/null
+++ b/package/contents/ui/configGeneral.qml
@@ -0,0 +1,76 @@
+// SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+//
+// SPDX-License-Identifier: LGPL-2.1-or-later
+
+import QtCore
+import QtQuick
+import QtQuick.Controls as QQC2
+import QtQuick.Dialogs
+import QtQuick.Layouts
+
+import org.kde.kirigami as Kirigami
+import org.kde.kcmutils as KCM
+
+KCM.SimpleKCM {
+    property alias cfg_passwordStoreDirectory: directoryField.text
+
+    Kirigami.FormLayout {
+        RowLayout {
+            Kirigami.FormData.label: i18nc("@label:textbox", "Password store location:")
+            spacing: Kirigami.Units.smallSpacing
+
+            QQC2.TextField {
+                id: directoryField
+                Layout.preferredWidth: Kirigami.Units.gridUnit * 16
+                placeholderText: i18nc("@info:placeholder", "Default location")
+            }
+
+            QQC2.Button {
+                display: QQC2.AbstractButton.IconOnly
+                icon.name: "document-open-folder"
+                text: i18nc("@action:button", "Choose location…")
+
+                QQC2.ToolTip.text: text
+                QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+                QQC2.ToolTip.visible: hovered
+
+                onClicked: folderDialogComponent.incubateObject(this)
+            }
+        }
+
+        QQC2.Label {
+            Layout.fillWidth: true
+            text: i18nc("@info", "Leave empty to use $PASSWORD_STORE_DIR, or ~/.password-store if it is not set.")
+            font: Kirigami.Theme.smallFont
+            wrapMode: Text.Wrap
+        }
+    }
+
+    Component {
+        id: folderDialogComponent
+
+        FolderDialog {
+            readonly property url homeUrl: StandardPaths.writableLocation(StandardPaths.HomeLocation)
+
+            currentFolder: directoryField.text !== "" ? pathToUrl(directoryField.text) : homeUrl
+
+            onAccepted: {
+                directoryField.text = urlToPath(selectedFolder);
+                destroy();
+            }
+            onRejected: destroy()
+            Component.onCompleted: open()
+
+            function urlToPath(qmlUrl) {
+                return decodeURIComponent(new URL(qmlUrl).pathname);
+            }
+
+            function pathToUrl(path) {
+                if (path === "~" || path.startsWith("~/")) {
+                    path = urlToPath(homeUrl) + path.substring(1);
+                }
+                return "file://" + path.split("/").map(encodeURIComponent).join("/");
+            }
+        }
+    }
+}
